let labState=null,llnState=null;
function rng(seed){return function(){seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return ((t^t>>>14)>>>0)/4294967296}}
function choose(n,k){if(!Number.isInteger(n)||!Number.isInteger(k)||k<0||k>n)return 0;k=Math.min(k,n-k);let v=1;for(let i=1;i<=k;i++)v=v*(n-k+i)/i;return v}
function binProb(n,k,p){if(k<0||k>n)return 0;if(p===0)return k===0?1:0;if(p===1)return k===n?1:0;return choose(n,k)*p**k*(1-p)**(n-k)}
function hyperProb(N,M,n,k){return choose(M,k)*choose(N-M,n-k)/choose(N,n)}
function poissonProb(l,k){if(l===0)return k===0?1:0;let p=Math.exp(-l);for(let i=1;i<=k;i++)p*=l/i;return p}
function normalCDF(z){const sign=z<0?-1:1,x=Math.abs(z)/Math.sqrt(2),t=1/(1+.3275911*x);const erf=sign*(1-(((((1.061405429*t-1.453152027)*t)+1.421413741)*t-.284496736)*t+.254829592)*t*Math.exp(-x*x));return .5*(1+erf)}
function normalSample(mu,s){const u=Math.max(Number.MIN_VALUE,Math.random()),v=Math.random();return mu+s*Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v)}
function basicStats(a){if(!a.length)return {n:0,mean:NaN,variance:NaN,median:NaN,modes:[]};const sorted=[...a].sort((x,y)=>x-y),n=a.length,mean=a.reduce((x,y)=>x+y,0)/n,variance=a.reduce((sum,x)=>sum+(x-mean)**2,0)/n,mid=Math.floor(n/2),median=n%2?sorted[mid]:(sorted[mid-1]+sorted[mid])/2;const counts=new Map();a.forEach(x=>counts.set(x,(counts.get(x)||0)+1));let max=0,min=Infinity;for(const c of counts.values()){max=Math.max(max,c);min=Math.min(min,c)}const modes=max===1&&counts.size>1?[]:[...counts].filter(([_,n])=>n===max).map(([x])=>x).sort((x,y)=>x-y);return {n,mean,variance,median,modes,sorted,counts,min:sorted[0],max:sorted[n-1],range:sorted[n-1]-sorted[0]}}
function labTiles(items){return `<div class="lab-stats">${items.map(x=>`<div class="lab-stat"><strong>${esc(x.value)}</strong><span>${esc(x.label)}</span>${x.note?'<div class="small muted">'+esc(x.note)+'</div>':''}</div>`).join('')}</div>`}
function chartPart(text){return (typeof interfaceText==='function')?interfaceText(text):text}
function chartJoiner(){return (typeof LANG==='undefined'||LANG==='ru')?' по ':' · '}
function plot(xs,ys,opts={}){if(!xs.length)return '<div class="empty">Пока нет данных для графика.</div>';const W=640,H=opts.height||305,L=55,R=25,T=37,B=54,pw=W-L-R,ph=H-T-B;let xmin=opts.xMin??(opts.edges?opts.edges[0]:Math.min(...xs)),xmax=opts.xMax??(opts.edges?opts.edges.at(-1):Math.max(...xs));if(xmin===xmax){xmin-=.5;xmax+=.5}if(opts.labels){xmin=-.6;xmax=xs.length-.4}else if(opts.bars&&!opts.edges){const dx=xs.length>1?Math.min(...xs.slice(1).map((x,i)=>x-xs[i])):1;xmin-=dx*.55;xmax+=dx*.55}
const seriesMax=Math.max(...ys,...(opts.theory?.ys||[]),...(opts.other||[]),opts.reference??0,0.001);const ymin=opts.yMin??0,ymax=opts.yMax??seriesMax*1.16;const px=x=>L+(x-xmin)/(xmax-xmin)*pw,py=y=>T+ph-(y-ymin)/(ymax-ymin)*ph;
let out=`<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(opts.title||`${chartPart(opts.yLabel||'Значение')}${chartJoiner()}${chartPart(opts.xLabel||'X')}`)}"><title>${esc(opts.title||opts.yLabel||'График')}</title>`;
for(let i=0;i<=4;i++){const y=ymin+(ymax-ymin)*i/4;out+=`<line class="grid" x1="${L}" x2="${W-R}" y1="${py(y)}" y2="${py(y)}"/><text x="${L-9}" y="${py(y)+4}" text-anchor="end">${fmt(y,ymax<1?3:1)}</text>`}
out+=`<line class="axis" x1="${L}" x2="${W-R}" y1="${T+ph}" y2="${T+ph}"/><text x="${L}" y="17" style="font-size:11px">${esc(opts.yLabel||'Значение')}</text><text x="${L+pw/2}" y="${H-6}" text-anchor="middle" style="font-size:11px">${esc(opts.xLabel||'Значение X')}</text>`;
let tickValues=opts.edges||xs;const step=Math.max(1,Math.ceil(tickValues.length/9));const ticks=tickValues.filter((_,i)=>i%step===0||i===tickValues.length-1);for(const x of ticks){const label=opts.labels?opts.labels[x]:opts.tailStart&&x===opts.tailStart?'≥'+x:fmt(x,2);out+=`<text x="${px(x)}" y="${T+ph+22}" text-anchor="middle" style="font-size:${opts.labels?10:11}px">${esc(label)}</text>`}
if(opts.reference!==undefined&&opts.reference>=ymin&&opts.reference<=ymax)out+=`<line class="reference" x1="${L}" x2="${W-R}" y1="${py(opts.reference)}" y2="${py(opts.reference)}"/>`;
if(opts.bars){for(let i=0;i<xs.length;i++){const x=xs[i],y=ys[i];let left,right;if(opts.edges){left=px(opts.edges[i]);right=px(opts.edges[i+1])}else{const dx=xs.length>1?Math.min(i?x-xs[i-1]:xs[1]-x,i<xs.length-1?xs[i+1]-x:x-xs[i-1]):1;const width=Math.min(pw/Math.max(xs.length,2)*.68,dx/(xmax-xmin)*pw*.68);left=px(x)-width/2;right=left+width}out+=`<rect class="bar" x="${left}" y="${py(y)}" width="${Math.max(0,right-left)}" height="${Math.max(0,py(ymin)-py(y))}" ${opts.hist?'stroke="var(--surface)" stroke-width=".6"':'rx="3"'}><title>${esc(opts.labels?opts.labels[x]:opts.edges?`[${fmt(opts.edges[i])};${fmt(opts.edges[i+1])}${i===xs.length-1?']':')'}`:x)}: ${fmt(y,6)}</title></rect>`}}
const line=(ax,ay,cls)=>`<path class="${cls}" d="${ax.map((x,i)=>`${i?'L':'M'}${px(x).toFixed(2)},${py(ay[i]).toFixed(2)}`).join(' ')}"/>`;
if(opts.line){out+=line(xs,ys,'line');if(xs.length<=30)for(let i=0;i<xs.length;i++)out+=`<circle class="dot" cx="${px(xs[i])}" cy="${py(ys[i])}" r="3.5"><title>${esc(xs[i])}: ${fmt(ys[i],6)}</title></circle>`}
if(opts.other)out+=line(xs,opts.other,'line2');if(opts.theory)out+=line(opts.theory.xs,opts.theory.ys,'line2');for(const ref of opts.vrefs||[]){out+=`<line x1="${px(ref.value)}" x2="${px(ref.value)}" y1="${T+8}" y2="${T+ph}" stroke="${ref.color||'var(--orange)'}" stroke-width="1.6" stroke-dasharray="4 4"/><text x="${px(ref.value)+5}" y="${T+3}" style="font-size:10px">${esc(ref.label)}</text>`}out+='</svg>';return `<div class="chart-wrap">${out}</div>`}
function densityPlot(a,b,c,d){const W=640,H=290,L=55,R=25,T=38,B=52,pw=W-L-R,ph=H-T-B,base=H-B,maxY=1/(b-a)*1.5,px=x=>L+(x-a)/(b-a)*pw,py=y=>base-y/maxY*ph,f=1/(b-a),prob=Math.max(0,Math.min(b,d)-Math.max(a,c))/(b-a);return `<div class="chart-wrap"><svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Плотность равномерной величины и выделенная площадь ${fmt(prob)}"><title>Вероятность равна площади: ${fmt(prob)}</title>${[0,1,2,3].map(i=>`<line class="grid" x1="${L}" x2="${W-R}" y1="${py(maxY*i/3)}" y2="${py(maxY*i/3)}"/><text x="${L-8}" y="${py(maxY*i/3)+4}" text-anchor="end">${fmt(maxY*i/3,3)}</text>`).join('')}<rect x="${px(c)}" y="${py(f)}" width="${Math.max(0,px(d)-px(c))}" height="${base-py(f)}" fill="var(--accent)" opacity=".25"/><path class="line" d="M${L},${base} L${L},${py(f)} L${W-R},${py(f)} L${W-R},${base}"/><line class="axis" x1="${L}" x2="${W-R}" y1="${base}" y2="${base}"/>${[a,c,d,b].filter((x,i,all)=>all.indexOf(x)===i).map(x=>`<text x="${px(x)}" y="${base+21}" text-anchor="middle">${fmt(x)}</text>`).join('')}<text x="${L}" y="18" style="font-size:11px">Плотность f(x)</text><text x="${L+pw/2}" y="${H-7}" text-anchor="middle">Значение X</text>${d>c?`<text x="${px((c+d)/2)}" y="${py(f)+29}" text-anchor="middle" style="fill:var(--accent-dark);font-weight:750">P = ${fmt(prob)}</text>`:''}</svg></div>`}
const PRESETS={marks:{title:'Отметки учеников',data:[4,3,5,2,4,5,3,4,5,5]},heights:{title:'Рост · учебные данные',data:[156,161,168,172,159,175,164,170,181,165,174,169,158,166,172,177,163,180,171,167]},rain:{title:'Осадки · из презентации',data:[50.3,48.7,38.5,39.8,40.1,45.3,45.9,41.4,47.6,44.4,40.3,39.5,42.6,43.2,41.7,40.8,44.1,46.6,50.1,50.7,49.2,49.6,45.4,41.3,40.2,38.7,39.6,49.8,42.2,43.5]}};
function parseDataset(s){let raw=s.trim();if(!raw)throw Error('Введите хотя бы одно наблюдение.');let parts=raw.split(/[;\s]+/).filter(Boolean);if(parts.length===1&&(raw.match(/,/g)||[]).length>=2)parts=raw.split(',');if(parts.length>2000)throw Error('Для этой учебной лаборатории используйте не более 2000 наблюдений.');const a=parts.map(numeric);if(a.some(x=>x===null||Math.abs(x)>1e9))throw Error('Проверьте числа. Разделяйте наблюдения точкой с запятой или пробелом; десятичная запятая допустима. Модуль числа не больше 10⁹.');return a}
function dataString(a){return a.map(v=>String(v).replace('.',',')).join('; ')}
function renderLab(s,panel){const type=s.lab;if(type==='ordered-series')renderOrderedSeriesLab(panel);else if(type==='series'||type==='variation')renderSeriesLab(s,panel);else if(type==='frequency')renderFrequencyLab(panel);else if(type==='tendency')renderTendencyLab(panel);else if(type==='lln')renderLLN(panel);else if(type==='density')renderDensityLab(panel);else if(type==='bayes')renderBayesLab(panel);else if(type==='roulette')renderRouletteLab(panel);else if(type==='research')renderResearchLab(panel);else if(type==='sampling')renderSamplingLab(panel);else renderDistributionLab(type,panel)}
function labHead(title,desc){return `<header class="lab-header"><span class="eyebrow">ЛАБОРАТОРИЯ · НАБЛЮДАЙТЕ И ОБЪЯСНЯЙТЕ</span><h2>${title}</h2><p>${desc}</p></header>`}
function renderSeriesLab(s,panel){const variation=s.lab==='variation',preset=variation?'rain':'marks';labState={kind:'series',mode:variation?'interval':'discrete',data:pendingSeriesData?.length?[...pendingSeriesData]:PRESETS[preset].data};pendingSeriesData=null;panel.innerHTML=labHead(variation?'Постройте свой вариационный ряд':'От наблюдений — к упорядоченному ряду',variation?'Один набор данных, два способа представления. Сравните точные значения и группировку по интервалам.':'Введите данные, найдите размах и увидьте распределение. Ни один пустой элемент не превратится в лишний ноль.')+`<div class="lab-controls"><div class="between" style="margin-bottom:15px"><div class="segmented"><button id="mode-discrete" class="${variation?'':'active'}" onclick="seriesMode('discrete')">Дискретный ряд</button><button id="mode-interval" class="${variation?'active':''}" onclick="seriesMode('interval')">Интервальный ряд</button></div><select style="width:190px;font-size:11px" aria-label="Набор данных" onchange="setPreset(this.value)">${Object.entries(PRESETS).map(([k,v])=>`<option value="${k}" ${k===preset?'selected':''}>${v.title}</option>`).join('')}</select></div><label class="small muted" for="series-data">Наблюдения · разделитель «;» или пробел</label><textarea id="series-data" rows="3">${dataString(labState.data)}</textarea><p class="control-hint">Например: 1,5; 2,5; 3. Допускаются отрицательные значения. Процент и простая дробь также читаются как числа.</p><div id="bin-control" class="${variation?'':'hidden'}" style="max-width:330px;margin:15px 0"><div class="range-label"><label for="series-bins">Число равных интервалов</label><output id="bin-output">6</output></div><input type="range" id="series-bins" min="1" max="15" value="6" oninput="updateSeries()"></div><div class="row wrap" style="margin-top:16px"><button class="btn primary" onclick="updateSeries()">Построить и рассчитать</button><button class="btn" onclick="suggestBins()">Правило Стерджеса</button><button class="btn ghost" onclick="exportLab()">${ico('download')} CSV данных</button></div><div id="sturges-result" class="lab-notice hidden" role="status" aria-live="polite"></div><div id="series-error" class="lab-result-error" aria-live="polite"></div></div><div id="series-result"></div>`;updateSeries()}
function setPreset(key){$('series-data').value=dataString(PRESETS[key].data);suggestBins(false);updateSeries()}
function suggestBins(run=true){try{const a=parseDataset($('series-data').value),raw=1+Math.log2(a.length),k=Math.max(1,Math.min(15,Math.ceil(raw)));$('series-bins').value=k;if(run){labState.mode='interval';$('mode-discrete').classList.remove('active');$('mode-interval').classList.add('active');$('bin-control').classList.remove('hidden');updateSeries();const notice=$('sturges-result');notice.innerHTML=`<strong>Правило Стерджеса применено.</strong> n = ${a.length}; 1 + log₂ n = ${fmt(raw,4)}. ${F(`k=\\lceil 1+\\log_2 ${a.length}\\rceil=${k}`)}<br>Построено ${k} равных интервалов. Округление вверх — выбранная рекомендация, а не обязательное правило для любых данных.`;notice.classList.remove('hidden');math(notice)}}catch(e){$('series-error').textContent=e.message;$('sturges-result').classList.add('hidden');$('series-result').innerHTML='';labState.csv=[]}}
function seriesMode(mode){labState.mode=mode;$('mode-discrete').classList.toggle('active',mode==='discrete');$('mode-interval').classList.toggle('active',mode==='interval');$('bin-control').classList.toggle('hidden',mode!=='interval');updateSeries()}
function binData(data,k,a=null,b=null){a=a??Math.min(...data);b=b??Math.max(...data);if(a===b){a-=.5;b+=.5}const h=(b-a)/k,edges=Array.from({length:k+1},(_,i)=>a+i*h);edges[k]=b;const counts=Array(k).fill(0);for(const x of data){let q=(x-a)/h;const nearest=Math.round(q);if(Math.abs(q-nearest)<1e-10)q=nearest;let i=Math.floor(q);i=Math.min(k-1,Math.max(0,i));counts[i]++}return {a,b,h,edges,counts,mids:edges.slice(0,-1).map((v,i)=>(v+edges[i+1])/2)}}
function updateSeries(){if($('sturges-result'))$('sturges-result').classList.add('hidden');try{const a=parseDataset($('series-data').value),st=basicStats(a),k=Number($('series-bins').value);labState.data=a;labState.csv=a;$('series-error').textContent='';$('bin-output').textContent=k;let visual='',table='',explanation='';if(labState.mode==='discrete'){const values=[...st.counts.keys()].sort((x,y)=>x-y),counts=values.map(x=>st.counts.get(x));visual=plot(values,counts,{line:true,yLabel:'Абсолютная частота nᵢ',xLabel:'Значение xᵢ'});table=`<thead><tr><th>Значение xᵢ</th><th>Частота nᵢ</th><th>Доля wᵢ</th></tr></thead><tbody>${values.slice(0,100).map((x,i)=>`<tr><td>${fmt(x,6)}</td><td>${counts[i]}</td><td>${fmt(counts[i]/a.length,5)}</td></tr>`).join('')}</tbody><tfoot><tr><td>Итого</td><td>${a.length}</td><td>1</td></tr></tfoot>`;explanation='Полигон соединяет точки (значение; частота). Расстояния по оси X соответствуют реальным числам.'+(values.length>100?' В таблице показаны первые 100 значений; итоги и график используют все данные.':'')}else{const b=binData(a,k),rel=b.counts.map(n=>n/a.length),density=rel.map(w=>w/b.h);visual=plot(b.mids,density,{edges:b.edges,bars:true,hist:true,yLabel:'Относительная плотность wᵢ/h',xLabel:'Границы интервалов'});table=`<thead><tr><th>Интервал</th><th>Середина mᵢ</th><th>Частота nᵢ</th><th>Доля wᵢ</th><th>Высота wᵢ/h</th></tr></thead><tbody>${b.counts.map((n,i)=>`<tr><td>[${fmt(b.edges[i],3)}; ${fmt(b.edges[i+1],3)}${i===k-1?']':')'}</td><td>${fmt(b.mids[i])}</td><td>${n}</td><td>${fmt(rel[i],5)}</td><td>${fmt(density[i],5)}</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="2">Итого</td><td>${a.length}</td><td>1</td><td>Площадь = 1</td></tr></tfoot>`;explanation=`Ширина h = ${fmt(b.h,6)}. Последний интервал включает максимум. Высоты — относительные частоты, делённые на ширину: площадь каждого прямоугольника равна доле наблюдений. Границы показаны округлённо; подсчёт выполнен без округления.`+(st.range===0?' Все значения совпали; для изображения выбран условный диапазон ширины 1 вокруг этого значения.':'')}
$('series-result').innerHTML=labTiles([{value:st.n,label:'Объём n'},{value:fmt(st.min),label:'Минимум'},{value:fmt(st.max),label:'Максимум'},{value:fmt(st.range),label:'Размах R'}])+`<div class="card lab-visual"><h3>${labState.mode==='discrete'?'Полигон частот':'Гистограмма относительных частот'}</h3>${visual}<div class="lab-notice">${esc(explanation)}</div><div class="table-scroll"><table>${table}</table></div></div><div class="card"><h3 style="font-size:16px">Упорядоченные данные</h3><div class="sample-row">${esc(dataString(st.sorted))}</div><p class="small muted" style="margin-top:13px">Вопрос для себя: что сохраняется, а что теряется при интервальной группировке?</p></div>`;math($('series-result'))}catch(e){$('series-error').textContent=e.message;$('series-result').innerHTML='';labState.csv=[]}}
function renderFrequencyLab(panel){labState={kind:'frequency'};panel.innerHTML=labHead('Выберите правильный знаменатель','В выборке 100 учеников. B — ученики, которые посещают спортивную секцию; A — ученики, которые идут в школу пешком. Общий объём всегда 100. Меняйте число учеников в секции и число пришедших пешком внутри и вне этой группы.')+`<div class="lab-controls"><div class="control-grid"><div><div class="range-label"><label for="freq-group">Посещают секцию · группа B</label><output id="freq-group-value"></output></div><input type="range" min="1" max="100" value="40" id="freq-group" oninput="updateFrequency()"></div><div><div class="range-label"><label for="freq-in">Идут пешком среди посещающих секцию · A ∩ B</label><output id="freq-in-value"></output></div><input type="range" min="0" max="40" value="30" id="freq-in" oninput="updateFrequency()"></div><div><div class="range-label"><label for="freq-out">Идут пешком среди остальных · A вне B</label><output id="freq-out-value"></output></div><input type="range" min="0" max="60" value="10" id="freq-out" oninput="updateFrequency()"></div></div></div><div id="frequency-result"></div>`;updateFrequency()}
function updateFrequency(){const N=100,b=Number($('freq-group').value);$('freq-in').max=b;$('freq-out').max=N-b;const ab=Number($('freq-in').value),outside=Number($('freq-out').value),a=ab+outside;for(const [id,v]of [['group',b],['in',ab],['out',outside]])$('freq-'+id+'-value').textContent=v;labState.csv=[['B и A',ab],['B и не A',b-ab],['не B и A',outside],['не B и не A',N-b-outside]];labState.csvHeaders=['Категория','Частота'];$('frequency-result').innerHTML=labTiles([{value:b,label:'Число в группе B'},{value:ab,label:'Число A ∩ B'},{value:fmt(a/N),label:'Частота A среди всех'},{value:fmt(ab/b),label:'Частота A внутри B'}])+`<div class="card"><h3>Одна таблица — два вопроса</h3><div class="table-scroll"><table><thead><tr><th>Группа</th><th>A: идут пешком</th><th>Не A: не идут пешком</th><th>Всего</th></tr></thead><tbody><tr><td>B: посещают секцию</td><td>${ab}</td><td>${b-ab}</td><td>${b}</td></tr><tr><td>Не B: не посещают секцию</td><td>${outside}</td><td>${N-b-outside}</td><td>${N-b}</td></tr></tbody><tfoot><tr><td>Итого</td><td>${a}</td><td>${N-a}</td><td>100</td></tr></tfoot></table></div><div class="lab-notice">Частота A среди всех: ${F(`w(A)=${a}/100=${fmt(a/N)}`)}. Частота A внутри B: ${F(`w(A\\mid B)=${ab}/${b}=${fmt(ab/b)}`)}.<br>Измените число A вне B: общая частота изменится, но условная частота внутри B останется прежней.</div><button class="btn" onclick="exportLab()">${ico('download')} Скачать таблицу</button></div>`;math($('frequency-result'))}
function renderTendencyLab(panel){labState={kind:'tendency'};panel.innerHTML=labHead('Как выброс влияет на «средний» результат?','Перемещайте последнее наблюдение или замените весь набор. Сравните среднее, медиану и моду на одном графике.')+`<div class="lab-controls"><label class="small muted" for="tend-data">Исходные данные · разделитель «;»</label><textarea id="tend-data" rows="2">2; 3; 3; 4; 5; 7; 20</textarea><div style="margin:18px 0;max-width:460px"><div class="range-label"><label for="tend-outlier">Последнее наблюдение</label><output id="outlier-value">20</output></div><input type="range" min="7" max="100" value="20" id="tend-outlier" oninput="changeOutlier()"></div><button class="btn primary" onclick="updateTendency()">Рассчитать</button><div class="lab-result-error" id="tendency-error" aria-live="polite"></div></div><div id="tendency-result"></div>`;updateTendency()}
function changeOutlier(){try{const a=parseDataset($('tend-data').value);a[a.length-1]=Number($('tend-outlier').value);$('tend-data').value=dataString(a);$('outlier-value').textContent=a.at(-1);updateTendency()}catch(e){$('tendency-error').textContent=e.message}}
function updateTendency(){try{const a=parseDataset($('tend-data').value),st=basicStats(a),x=[...st.counts.keys()].sort((x,y)=>x-y),y=x.map(v=>st.counts.get(v));labState.csv=a;$('tendency-error').textContent='';$('outlier-value').textContent=fmt(a.at(-1));$('tendency-result').innerHTML=labTiles([{value:st.n,label:'Объём n'},{value:fmt(st.mean),label:'Среднее x̄'},{value:fmt(st.median),label:'Медиана Me'},{value:st.modes.length?st.modes.map(x=>fmt(x)).join('; '):'Не выражена',label:'Мода Mo'}])+`<div class="card lab-visual"><h3>Где центр ваших данных?</h3>${plot(x,y,{bars:true,yLabel:'Частота',xLabel:'Значение',vrefs:[{value:st.mean,label:'Среднее',color:'var(--orange)'},{value:st.median,label:'Медиана',color:'var(--accent)'}]})}<div class="chart-legend"><span><i class="legend-dot orange"></i>Среднее: ${fmt(st.mean)}</span><span><i class="legend-dot"></i>Медиана: ${fmt(st.median)}</span></div><div class="sample-row">${esc(dataString(st.sorted))}</div><div class="lab-notice">Среднее использует все величины, а медиана зависит от центральных позиций. Если все наблюдения различны, считаем моду невыраженной; несколько повторяющихся максимумов дают несколько мод. ${F(`\\bar{x}=${fmt(a.reduce((x,y)=>x+y,0))}/${st.n}=${fmt(st.mean)}`)}</div><button class="btn" onclick="exportLab()">${ico('download')} CSV наблюдений</button></div>`;math($('tendency-result'))}catch(e){$('tendency-error').textContent=e.message;$('tendency-result').innerHTML=''}}
const DIST_TITLES={dice:'Кубики · сумма очков',coins:'Монеты · число орлов',binomial:'Биномиальное распределение',geometric:'До первого успеха',hypergeometric:'Выбор без возвращения',poisson:'Пуассон · число событий',lottery:'Призы · чистый результат',custom:'Собственный дискретный закон',uniform:'Равномерная на интервале',height:'Рост · нормальная модель',temperature:'Температура · нормальная модель',rainfall:'Осадки · экспоненциальная модель',waiting:'Ожидание · экспоненциальная модель'};
const DIST_DEFAULTS={dice:{dice:1},coins:{n:2,p:.5},binomial:{n:8,p:.5},geometric:{p:.3},hypergeometric:{N:10,M:3,n:4},poisson:{lambda:2},lottery:{},custom:{},uniform:{a:0,b:10},height:{mu:170,sigma:7},temperature:{mu:12,sigma:8},rainfall:{mean:4},waiting:{mean:5}};
function paramField(key,title,value,min,max,step=1){return `<div class="control-field"><label for="param-${key}">${title}</label><input id="param-${key}" data-param="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${value}" oninput="distributionChanged()"></div>`}
function distControls(mode){const p=DIST_DEFAULTS[mode];if(mode==='dice')return paramField('dice','Количество кубиков',p.dice,1,3);if(mode==='coins'||mode==='binomial')return paramField('n',mode==='coins'?'Количество монет':'Число испытаний n',p.n,1,40)+paramField('p','Вероятность успеха p',p.p,0,1,.05);if(mode==='geometric')return paramField('p','Вероятность успеха p',p.p,.05,1,.05);if(mode==='hypergeometric')return paramField('N','Всего объектов N',p.N,2,60)+paramField('M','Объектов нужной категории M',p.M,0,60)+paramField('n','Размер выборки n',p.n,1,60);if(mode==='poisson')return paramField('lambda','Среднее число событий λ',p.lambda,0,15,.5);if(mode==='uniform')return paramField('a','Левая граница a',p.a,-1000,1000,.5)+paramField('b','Правая граница b',p.b,-1000,1000,.5);if(mode==='height'||mode==='temperature')return paramField('mu','Среднее μ',p.mu,-1000,1000,.5)+paramField('sigma','Стандартное отклонение σ',p.sigma,.1,100,.5);if(mode==='rainfall'||mode==='waiting')return paramField('mean','Среднее m',p.mean,.1,100,.5);if(mode==='custom')return `<div class="control-field"><label for="custom-values">Значения xᵢ · через «;»</label><input id="custom-values" value="1; 4" oninput="distributionChanged()"></div><div class="control-field"><label for="custom-probs">Вероятности pᵢ · через «;»</label><input id="custom-probs" value="0,4; 0,6" oninput="distributionChanged()"></div>`;return '<p class="small muted">Чистые результаты −100, 100 и 900 с вероятностями 0,8; 0,15; 0,05. Стоимость уже учтена. Это учебная модель, не предложение участвовать в игре.</p>'}
function renderDistributionLab(mode,panel){if(!DIST_TITLES[mode])mode='dice';labState={kind:'dist',mode,samples:[],model:null};panel.innerHTML=labHead('Случайность в модели и в эксперименте','Выберите распределение, настройте параметры и проведите серию опытов. Теоретические вероятности не подменяются наблюдаемыми частотами.')+`<div class="lab-controls"><div class="control-grid" style="margin-bottom:18px"><div class="control-field"><label for="dist-mode">Модель эксперимента</label><select id="dist-mode" onchange="changeDistribution(this.value)">${Object.entries(DIST_TITLES).map(([k,v])=>`<option value="${k}" ${mode===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="control-field"><label for="dist-trials">Наблюдений в серии</label><select id="dist-trials"><option value="100">100</option><option value="1000" selected>1 000</option><option value="10000">10 000</option></select></div></div><div class="control-grid" id="dist-params">${distControls(mode)}</div><div class="row wrap" style="margin-top:20px"><button class="btn primary" onclick="runDistribution(false)">${ico('flask')} Провести эксперимент</button><button class="btn" onclick="runDistribution(true)">Добавить серию</button><button class="btn ghost" onclick="clearDistribution()">Очистить опыт</button><button class="btn ghost" onclick="exportLab()">${ico('download')} CSV</button></div><div class="lab-result-error" id="dist-error" aria-live="polite"></div><p class="control-hint">При изменении параметров прежние наблюдения очищаются: разные законы нельзя смешивать в одну серию.</p></div><div id="distribution-result"></div>`;distributionChanged()}
function changeDistribution(mode){labState.mode=mode;labState.samples=[];$('dist-params').innerHTML=distControls(mode);distributionChanged()}
function readParams(){const p={};for(const el of document.querySelectorAll('[data-param]')){if(el.value.trim()==='')throw Error('Заполните все параметры.');const n=numeric(el.value);if(n===null||n<Number(el.min)||n>Number(el.max))throw Error('Параметр «'+el.previousElementSibling.textContent+'» должен быть в диапазоне '+el.min+'…'+el.max+'.');if(el.step==='1'&&!Number.isInteger(n))throw Error('Счётные параметры должны быть целыми числами.');p[el.dataset.param]=n}return p}
function makeModel(mode,p){let values=[],probs=[],mean=0,variance=0,sample,density,cdf,domain,tailStart=null,continuous=false;
if(mode==='dice'){let dist=[1];for(let d=0;d<p.dice;d++){const next=Array(dist.length+6).fill(0);for(let x=0;x<dist.length;x++)for(let f=1;f<=6;f++)next[x+f]+=dist[x]/6;dist=next}values=Array.from({length:5*p.dice+1},(_,i)=>p.dice+i);probs=values.map(x=>dist[x]);mean=3.5*p.dice;variance=35/12*p.dice;sample=()=>{let sum=0;for(let i=0;i<p.dice;i++)sum+=1+Math.floor(Math.random()*6);return sum}}
if(mode==='coins'||mode==='binomial'){values=Array.from({length:p.n+1},(_,i)=>i);probs=values.map(k=>binProb(p.n,k,p.p));mean=p.n*p.p;variance=mean*(1-p.p);sample=()=>{let successes=0;for(let i=0;i<p.n;i++)successes+=Math.random()<p.p?1:0;return successes}}
if(mode==='geometric'){let K=p.p===1?1:Math.min(120,Math.ceil(Math.log(1e-5)/Math.log(1-p.p)));values=Array.from({length:K},(_,i)=>i+1);probs=values.map(k=>(1-p.p)**(k-1)*p.p);if(p.p!==1){tailStart=K+1;values.push(tailStart);probs.push((1-p.p)**K)}mean=1/p.p;variance=(1-p.p)/p.p**2;sample=()=>p.p===1?1:Math.floor(Math.log(1-Math.random())/Math.log(1-p.p))+1}
if(mode==='hypergeometric'){if(p.M>p.N||p.n>p.N)throw Error('M и n не могут превышать N. Измените параметры выборки.');const lo=Math.max(0,p.n-(p.N-p.M)),hi=Math.min(p.n,p.M);values=Array.from({length:hi-lo+1},(_,i)=>lo+i);probs=values.map(k=>hyperProb(p.N,p.M,p.n,k));mean=p.n*p.M/p.N;variance=p.n*(p.M/p.N)*(1-p.M/p.N)*(p.N-p.n)/(p.N-1);sample=()=>{let N=p.N,M=p.M,s=0;for(let i=0;i<p.n;i++){if(Math.random()<M/N){s++;M--}N--}return s}}
if(mode==='poisson'){const K=Math.max(1,Math.ceil(p.lambda+8*Math.sqrt(p.lambda)+10));values=Array.from({length:K+1},(_,i)=>i);probs=values.map(k=>poissonProb(p.lambda,k));const tail=Math.max(0,1-probs.reduce((a,b)=>a+b,0));if(tail>1e-14){tailStart=K+1;values.push(tailStart);probs.push(tail)}mean=variance=p.lambda;sample=()=>{if(!p.lambda)return 0;const L=Math.exp(-p.lambda);let product=1,k=0;do{k++;product*=Math.random()}while(product>L);return k-1}}
if(mode==='lottery'){values=[-100,100,900];probs=[.8,.15,.05]}
if(mode==='custom'){values=parseDataset($('custom-values').value);probs=parseDataset($('custom-probs').value);if(values.length!==probs.length)throw Error('Число значений и вероятностей должно совпадать.');if(values.length>40)throw Error('Для собственного закона используйте не больше 40 различных значений.');if(new Set(values).size!==values.length)throw Error('Каждое значение должно встречаться в таблице один раз. Объедините повторяющиеся значения.');if(probs.some(v=>v<0||v>1))throw Error('Все вероятности должны находиться между 0 и 1.');const sum=probs.reduce((a,b)=>a+b,0);if(Math.abs(sum-1)>1e-6)throw Error('Сумма вероятностей должна быть 1. Сейчас: '+fmt(sum,8)+'.');probs=probs.map(v=>v/sum);const sorted=values.map((x,i)=>[x,probs[i]]).sort((a,b)=>a[0]-b[0]);values=sorted.map(x=>x[0]);probs=sorted.map(x=>x[1])}
if(mode==='lottery'||mode==='custom'){mean=values.reduce((s,x,i)=>s+x*probs[i],0);variance=values.reduce((s,x,i)=>s+(x-mean)**2*probs[i],0);sample=()=>{const u=Math.random();let sum=0;for(let i=0;i<values.length;i++){sum+=probs[i];if(u<sum)return values[i]}return values.at(-1)}}
if(mode==='uniform'){if(p.a>=p.b)throw Error('Левая граница должна быть меньше правой: a < b.');continuous=true;mean=(p.a+p.b)/2;variance=(p.b-p.a)**2/12;domain=[p.a,p.b];density=x=>x>=p.a&&x<=p.b?1/(p.b-p.a):0;cdf=x=>Math.max(0,Math.min(1,(x-p.a)/(p.b-p.a)));sample=()=>p.a+Math.random()*(p.b-p.a)}
if(mode==='height'||mode==='temperature'){continuous=true;mean=p.mu;variance=p.sigma**2;domain=[p.mu-4*p.sigma,p.mu+4*p.sigma];density=x=>Math.exp(-.5*((x-p.mu)/p.sigma)**2)/(p.sigma*Math.sqrt(2*Math.PI));cdf=x=>normalCDF((x-p.mu)/p.sigma);sample=()=>normalSample(p.mu,p.sigma)}
if(mode==='rainfall'||mode==='waiting'){continuous=true;mean=p.mean;variance=p.mean**2;domain=[0,8*p.mean];density=x=>x<0?0:Math.exp(-x/p.mean)/p.mean;cdf=x=>x<0?0:1-Math.exp(-x/p.mean);sample=()=>-p.mean*Math.log(1-Math.random())}
return {mode,params:p,values,probs,mean,variance,sample,continuous,density,cdf,domain,tailStart}}
function distributionChanged(){labState.samples=[];labState.csv=[];try{labState.model=makeModel(labState.mode,readParams());$('dist-error').textContent='';showDistribution()}catch(e){labState.model=null;$('dist-error').textContent=e.message;$('distribution-result').innerHTML=''}}
function runDistribution(add){if(!labState.model){toast('Сначала исправьте параметры модели.',true);return}const n=Number($('dist-trials').value);if(!add)labState.samples=[];if(labState.samples.length+n>100000){toast('Достаточно 100 000 наблюдений. Очистите опыт для новой серии.',true);return}for(let i=0;i<n;i++)labState.samples.push(labState.model.sample());labState.csv=labState.samples;showDistribution()}
function clearDistribution(){labState.samples=[];labState.csv=[];showDistribution()}
function showDistribution(){const m=labState.model,a=labState.samples,n=a.length,st=basicStats(a);let table='',chart='',notice='',probSum=0;
if(!m.continuous){const counts=Array(m.values.length).fill(0);for(const x of a){let i=m.tailStart&&x>=m.tailStart?m.values.length-1:m.values.indexOf(x);if(i>=0)counts[i]++}const rel=counts.map(x=>n?x/n:0);probSum=m.probs.reduce((s,x)=>s+x,0);chart=plot(m.values,rel,{bars:true,other:m.probs,tailStart:m.tailStart,yLabel:'Вероятность / относительная частота',xLabel:m.mode==='geometric'?'Номер попытки':'Значение X'});table=`<thead><tr><th>X</th><th>Теория pᵢ</th><th>Частота nᵢ</th><th>Опыт wᵢ</th></tr></thead><tbody>${m.values.map((x,i)=>`<tr><td>${m.tailStart===x?'≥ '+x:fmt(x,6)}</td><td>${fmt(m.probs[i],6)}</td><td>${counts[i]}</td><td>${n?fmt(rel[i],6):'—'}</td></tr>`).join('')}</tbody><tfoot><tr><td>Итого</td><td>${fmt(probSum,6)}</td><td>${n}</td><td>${n?'1':'—'}</td></tr></tfoot>`;notice='Точки линии — теоретические вероятности; столбцы — относительные частоты опыта. Соединение точек не превращает дискретную величину в непрерывную.'+(m.tailStart?' Последняя корзина объединяет хвост X ≥ '+m.tailStart+'; теоретические характеристики считаются по полному закону.':'')}
else{let left=m.domain[0],right=m.domain[1];if(a.length){left=Math.min(left,st.min);right=Math.max(right,st.max)}const b=binData(a.length?a:[left,right],10,left,right);const counts=a.length?b.counts:Array(10).fill(0),rel=counts.map(x=>n?x/n:0),height=rel.map(x=>x/b.h);const tx=Array.from({length:180},(_,i)=>left+(right-left)*i/179),ty=tx.map(m.density);chart=plot(b.mids,height,{bars:true,hist:true,edges:b.edges,theory:{xs:tx,ys:ty},yLabel:'Плотность, 1/ед.',xLabel:'Значение X'});const theo=b.mids.map((_,i)=>Math.max(0,m.cdf(b.edges[i+1])-m.cdf(b.edges[i])));probSum=theo.reduce((s,x)=>s+x,0);table=`<thead><tr><th>Интервал</th><th>Теор. вероятность</th><th>Частота</th><th>Опытная доля</th><th>Высота wᵢ/h</th></tr></thead><tbody>${b.mids.map((_,i)=>`<tr><td>[${fmt(b.edges[i])}; ${fmt(b.edges[i+1])}${i===9?']':')'}</td><td>${fmt(theo[i],6)}</td><td>${counts[i]}</td><td>${n?fmt(rel[i],5):'—'}</td><td>${n?fmt(height[i],5):'—'}</td></tr>`).join('')}</tbody><tfoot><tr><td>В отображённом диапазоне</td><td>${fmt(probSum,6)}</td><td>${n}</td><td>${n?'1':'—'}</td><td>Площадь опыта = ${n?'1':'0'}</td></tr></tfoot>`;notice='У гистограммы высота wᵢ/h, а площадь — доля наблюдений. Линия показывает плотность модели, не вероятность точки. Все опытные данные входят в выбранный диапазон; у нормальной и экспоненциальной моделей вне графика может оставаться небольшой теоретический хвост. Данные о росте, температуре, осадках и ожидании — условные симуляции, не реальные измерения.'}
$('distribution-result').innerHTML=labTiles([{value:fmt(m.mean,4),label:'M(X) · теория'},{value:n?fmt(st.mean,4):'—',label:'Среднее · опыт',note:n+' наблюдений'},{value:fmt(m.variance,4),label:'D(X) · теория'},{value:n?fmt(st.variance,4):'—',label:'Дисперсия · опыт',note:'деление на n'}])+`<div class="card lab-visual"><div class="between"><h3>${m.continuous?'Гистограмма и плотность':'Закон распределения и частоты'}</h3><span class="pill">${m.continuous?'Непрерывная':'Дискретная'} модель</span></div>${chart}<div class="chart-legend"><span><i class="legend-dot orange"></i>${m.continuous?'Плотность модели':'Вероятности модели'}</span><span><i class="legend-dot"></i>Наблюдаемые частоты${m.continuous?' / ширина':''}</span></div><div class="lab-notice">${esc(notice)}<br>${F(`\\sigma(X)=\\sqrt{D(X)}=${fmt(Math.sqrt(m.variance),4)}`)}. ${n?'Опытное стандартное отклонение: '+fmt(Math.sqrt(st.variance),4)+'.':'Проведите эксперимент для сравнения.'}</div><div class="table-scroll" style="max-height:390px"><table>${table}</table></div></div><div class="card"><h3 style="font-size:16px">Попробуйте объяснить</h3><p class="small muted">Почему теоретическое ожидание может не совпасть с опытом? Как повлияет увеличение числа наблюдений? Повторите опыт, не меняя параметры, и сравните результаты.</p>${n?`<div class="sample-row" style="margin-top:14px">Первые наблюдения: ${esc(dataString(a.slice(0,20)))}${n>20?' …':''}</div>`:''}</div>`;math($('distribution-result'))}
function renderLLN(panel){llnState={heads:0,values:[],p:.5};labState={kind:'lln',csv:[]};panel.innerHTML=labHead('Независимая монета и закон больших чисел','Проведите новую серию или продолжите текущую. Увеличение числа бросков не меняет вероятность следующего исхода.')+`<div class="lab-controls"><div class="control-grid"><div><div class="range-label"><label for="lln-p">Вероятность орла p</label><output id="lln-p-value">0,5</output></div><input type="range" id="lln-p" min=".05" max=".95" step=".05" value=".5" oninput="changeLLNP()"></div><div class="control-field"><label for="lln-n">Размер серии</label><select id="lln-n"><option value="10">10</option><option value="100">100</option><option value="1000" selected>1 000</option><option value="10000">10 000</option></select></div></div><div class="row wrap" style="margin-top:20px"><button class="btn primary" onclick="runLLN(false)">Новая независимая серия</button><button class="btn" onclick="runLLN(true)">Продолжить текущую</button><button class="btn ghost" onclick="clearLLN()">Сбросить</button><button class="btn ghost" onclick="exportLab()">${ico('download')} CSV</button></div></div><div id="lln-result"></div>`;showLLN()}
function changeLLNP(){llnState.p=Number($('lln-p').value);$('lln-p-value').textContent=fmt(llnState.p,2);clearLLN()}
function clearLLN(){llnState.heads=0;llnState.values=[];labState.csv=[];showLLN()}
function runLLN(add){if(!add){llnState.heads=0;llnState.values=[]}const n=Number($('lln-n').value);if(llnState.values.length+n>100000){toast('Очистите серию: достигнуто 100 000 бросков.',true);return}for(let i=0;i<n;i++){const head=Math.random()<llnState.p?1:0;llnState.values.push(head);llnState.heads+=head}let h=0;labState.csv=llnState.values.map((v,i)=>{h+=v;return [i+1,v,h/(i+1)]});labState.csvHeaders=['Бросок','Орёл (1) / решка (0)','Накопленная частота'];showLLN()}
function showLLN(){const n=llnState.values.length,w=n?llnState.heads/n:NaN;let heads=0,x=[],y=[];const step=Math.max(1,Math.floor(n/600));for(let i=0;i<n;i++){heads+=llnState.values[i];if(i<10||i%step===0||i===n-1){x.push(i+1);y.push(heads/(i+1))}}$('lln-result').innerHTML=labTiles([{value:n,label:'Бросков'},{value:llnState.heads,label:'Орлов'},{value:n?fmt(w,5):'—',label:'Частота орла w'},{value:n?fmt(Math.abs(w-llnState.p),5):'—',label:'Отклонение |w−p|'}])+`<div class="card lab-visual"><h3>Как меняется относительная частота</h3>${n?plot(x,y,{line:true,yMax:1,reference:llnState.p,xLabel:'Число бросков n',yLabel:'Накопленная частота wₙ'}):'<div class="empty">Запустите серию и наблюдайте за линией частоты.</div>'}<div class="chart-legend"><span><i class="legend-dot"></i>Опытная частота</span><span><i class="legend-dot orange"></i>Теоретическая вероятность p = ${fmt(llnState.p,2)}</span></div><div class="coin-row">${llnState.values.slice(-16).map(v=>`<span class="coin ${v?'':'tail'}" title="${v?'Орёл':'Решка'}">${v?'О':'Р'}</span>`).join('')}</div><div class="lab-notice">Последние ${Math.min(n,16)} бросков показаны отдельно. Прошлая серия не создаёт «долга» монеты: вероятность следующего орла остаётся ${fmt(llnState.p,2)}. Линия частоты не обязана приближаться к p на каждом шаге. График длинных серий прореживается для наглядности; CSV содержит все броски.</div></div>`}
function renderDensityLab(panel){labState={kind:'density'};panel.innerHTML=labHead('Вероятность — это площадь','X равномерна на [0;10]. Плотность внутри равна 0,1. Изменяйте границы интервала, чтобы увидеть геометрический смысл вероятности.')+`<div class="lab-controls"><div class="grid2"><div><div class="range-label"><label for="density-left">Левая граница c</label><output id="density-left-value">2</output></div><input type="range" min="0" max="10" step=".5" value="2" id="density-left" oninput="updateDensity('left')"></div><div><div class="range-label"><label for="density-right">Правая граница d</label><output id="density-right-value">5</output></div><input type="range" min="0" max="10" step=".5" value="5" id="density-right" oninput="updateDensity('right')"></div></div></div><div id="density-result"></div>`;updateDensity()}
function updateDensity(changed){let c=Number($('density-left').value),d=Number($('density-right').value);if(c>d){if(changed==='left')$('density-right').value=d=c;else $('density-left').value=c=d}$('density-left-value').textContent=fmt(c);$('density-right-value').textContent=fmt(d);const p=(d-c)/10;labState.csv=[[c,d,.1,p]];labState.csvHeaders=['c','d','Плотность','Вероятность'];$('density-result').innerHTML=labTiles([{value:fmt(d-c),label:'Длина интервала'},{value:'0,1',label:'Плотность f(x)'},{value:fmt(p),label:'Вероятность интервала'},{value:fmtP(p),label:'Доля полной площади'}])+`<div class="card lab-visual"><h3>Площадь выделенного прямоугольника</h3>${densityPlot(0,10,c,d)}<div class="lab-notice">${F(`P(${c}\\le X\\le ${d})=(${d}-${c})\\cdot0{,}1=${fmt(p)}`)}.<br>${c===d?'Ширина равна нулю: вероятность отдельной точки — 0.':'Изменение границ меняет площадь, но не высоту постоянной плотности.'} Для непрерывной модели включение или исключение концов интервала не меняет вероятность.</div><button class="btn" onclick="exportLab()">${ico('download')} Сохранить расчёт</button></div>`;math($('density-result'))}
function renderBayesLab(panel){labState={kind:'bayes'};panel.innerHTML=labHead('Почему важно знать исходную долю брака?','Учебная линия из 10 000 изделий. Датчик может верно обнаружить дефект или дать ложный сигнал. Меняйте исходную долю брака и параметры датчика; сравнивайте, сколько дефектных среди всех отмеченных.')+`<div class="lab-controls"><div class="control-grid">${[['prevalence','Исходная доля дефектных изделий',.01,30,.01,1],['sensitivity','Обнаруживает дефектных · чувствительность',50,99,1,90],['specificity','Верно распознаёт исправные · специфичность',50,99,1,95]].map(([key,title,min,max,step,value])=>`<div><div class="range-label"><label for="bayes-${key}">${title}</label><output id="bayes-${key}-value"></output></div><input type="range" min="${min}" max="${max}" step="${step}" value="${value}" id="bayes-${key}" oninput="updateBayes()"></div>`).join('')}</div><p class="control-hint">Чувствительность считаем среди дефектных, специфичность — среди исправных. Это не доля дефектных среди сработавших сигналов.</p><div class="bayes-presets"><button class="btn sm" onclick="setBayesPreset('factory')">Исходный пример: брак 1%</button><button class="btn sm" onclick="setBayesPreset('rare')">Редкий признак: 1 на 10 000 · оба параметра 99%</button></div><p class="control-hint">1 на 10 000 — это 0,01%. Дробные количества в таблице — ожидаемые, а не результаты конкретной проверки.</p></div><div id="bayes-result"></div>`;updateBayes()}
function setBayesPreset(name){const values=name==='rare'?[.01,99,99]:[1,90,95];['prevalence','sensitivity','specificity'].forEach((key,i)=>$('bayes-'+key).value=values[i]);updateBayes()}
function updateBayes(){const prev=Number($('bayes-prevalence').value)/100,sens=Number($('bayes-sensitivity').value)/100,spec=Number($('bayes-specificity').value)/100;for(const [k,v]of [['prevalence',prev],['sensitivity',sens],['specificity',spec]])$('bayes-'+k+'-value').textContent=fmtP(v);const N=10000,yes=N*prev,no=N-yes,tp=yes*sens,fn=yes-tp,fp=no*(1-spec),tn=no-fp,ppv=tp/(tp+fp);labState.csv=[['Дефектные',tp,fn,yes],['Исправные',fp,tn,no]];labState.csvHeaders=['Состояние изделия','Датчик: дефект','Датчик: норма','Всего'];$('bayes-result').innerHTML=labTiles([{value:fmt(tp,2),label:'Верные сигналы «дефект»'},{value:fmt(fp,2),label:'Ложные сигналы «дефект»'},{value:fmt(tp+fp,2),label:'Все сигналы «дефект»'},{value:fmtP(ppv),label:'Дефектные среди отмеченных'}])+`<div class="card lab-visual"><h3>Сигнал «дефект» не всегда означает дефект</h3>${plot([0,1],[tp,fp],{bars:true,labels:['Верные сигналы','Ложные сигналы'],yLabel:'Ожидаемое число изделий',xLabel:'Датчик отметил «дефект»'})}<div class="table-scroll" style="margin-top:20px"><table><caption>Ожидаемые результаты проверки 10 000 изделий</caption><thead><tr><th scope="col">Состояние изделия</th><th scope="col">Датчик: «дефект»</th><th scope="col">Датчик: «норма»</th><th scope="col">Всего</th></tr></thead><tbody><tr><th scope="row">Дефектные</th><td>${fmt(tp,2)}</td><td>${fmt(fn,2)}</td><td>${fmt(yes,2)}</td></tr><tr><th scope="row">Исправные</th><td>${fmt(fp,2)}</td><td>${fmt(tn,2)}</td><td>${fmt(no,2)}</td></tr></tbody><tfoot><tr><th scope="row">Всего</th><td>${fmt(tp+fp,2)}</td><td>${fmt(fn+tn,2)}</td><td>10 000</td></tr></tfoot></table></div><div class="lab-notice"><strong>Какой знаменатель нужен?</strong> Все отмеченные изделия: ${fmt(tp,2)} + ${fmt(fp,2)} = ${fmt(tp+fp,2)}. Из них действительно дефектных ${fmt(tp,2)}. Искомая доля — ${fmt(tp,2)} / ${fmt(tp+fp,2)}, около <strong>${fmtP(ppv)}</strong>.<br>Числа в таблице — ожидаемые количества, поэтому при некоторых параметрах бывают дробными. Большая группа исправных может дать больше ложных сигналов, чем малая группа дефектных — верных.</div><button class="btn" onclick="exportLab()">${ico('download')} Скачать таблицу</button></div>`;math($('bayes-result'))}
function renderSamplingLab(panel){labState={kind:'sampling',samples:[],means:[],csv:[]};panel.innerHTML=labHead('Большая выборка не всегда хорошая','В учебной совокупности 1 000 объектов: 500 имеют результат 60, остальные 500 — 90. Среднее всей совокупности равно 75. Сравните случайный и удобный отбор.')+`<div class="lab-controls"><div class="grid2"><div><div class="range-label"><label for="sampling-n">Объём выборки</label><output id="sampling-n-value">100</output></div><input type="range" min="10" max="300" step="10" value="100" id="sampling-n" oninput="samplingChanged()"></div><div class="control-field"><label for="sampling-mode">Способ отбора</label><select id="sampling-mode" onchange="samplingChanged()"><option value="random">Случайно из всей совокупности</option><option value="biased">Только из группы с 90 баллами</option></select></div></div><div class="row wrap" style="margin-top:20px"><button class="btn primary" onclick="runSampling(1)">Собрать одну выборку</button><button class="btn" onclick="runSampling(20)">Сравнить 20 выборок</button><button class="btn ghost" onclick="exportLab()">${ico('download')} CSV</button></div></div><div id="sampling-result"></div>`;runSampling(1)}
function samplingChanged(){$('sampling-n-value').textContent=$('sampling-n').value;labState.samples=[];labState.means=[];labState.csv=[];$('sampling-result').innerHTML='<div class="empty">Параметры изменены. Соберите новую выборку.</div>'}
function runSampling(repeats){const n=Number($('sampling-n').value),biased=$('sampling-mode').value==='biased';labState.means=[];labState.csv=[];for(let r=0;r<repeats;r++){const pool=Array.from({length:biased?500:1000},(_,i)=>biased||i>=500?90:60);for(let i=0;i<n;i++){const j=i+Math.floor(Math.random()*(pool.length-i));[pool[i],pool[j]]=[pool[j],pool[i]]}const sample=pool.slice(0,n);const mean=sample.reduce((s,x)=>s+x,0)/n;labState.means.push(mean);labState.samples=sample;sample.forEach((x,i)=>labState.csv.push([r+1,i+1,x]))}labState.csvHeaders=['Выборка','Номер объекта','Баллы'];const st=basicStats(labState.samples),A=labState.samples.filter(x=>x===60).length,B=n-A;$('sampling-result').innerHTML=labTiles([{value:n,label:'Объём одной выборки'},{value:fmt(st.mean),label:'Среднее последней выборки'},{value:'75',label:'Среднее совокупности'},{value:fmt(st.mean-75),label:'Отклонение от 75'}])+`<div class="card lab-visual"><h3>${repeats>1?'Средние повторных выборок':'Состав вашей выборки'}</h3>${repeats>1?plot(labState.means.map((_,i)=>i+1),labState.means,{line:true,yMin:55,yMax:95,reference:75,xLabel:'Номер выборки',yLabel:'Средний балл'}):plot([0,1],[A,B],{bars:true,labels:['60 баллов','90 баллов'],yLabel:'Число выбранных объектов',xLabel:'Группа'})}<div class="lab-notice">${biased?'Удобный отбор берёт только группу с 90 баллами: увеличение n не исправляет смещение.':'При случайном отборе среднее колеблется вокруг 75; отдельная выборка не обязана содержать поровну обе группы.'} Отбор в каждой выборке выполняется без возвращения; между повторными выборками совокупность восстановлена.</div><div class="sample-row">В последней выборке: ${A} объектов с 60 и ${B} объектов с 90 баллами. Среднее = (60·${A}+90·${B})/${n} = ${fmt(st.mean)}.</div><p class="small muted" style="margin-top:15px">Вопрос для обсуждения: почему 300 удобных наблюдений могут быть хуже 30 случайных?</p></div>`}
function exportLab(){if(!labState?.csv?.length){toast('Сначала проведите опыт или рассчитайте данные.',true);return}const matrix=Array.isArray(labState.csv[0]);const headers=labState.csvHeaders||(matrix?labState.csv[0].map((_,i)=>'Столбец '+(i+1)):['Номер','Наблюдение X']);const rows=[headers,...labState.csv.map((r,i)=>matrix?r:[i+1,r])];download(new Blob(['\ufeff'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'СтатПрактикум — эксперимент.csv');toast('Результаты эксперимента подготовлены в CSV.')}

// Basic ordered data: no discrete/interval grouping in the main lesson.
function renderOrderedSeriesLab(panel){labState={kind:'ordered-series',data:[...PRESETS.marks.data],csv:[]};panel.innerHTML=labHead('Составьте обычный вариационный ряд','Сортировка меняет только порядок. Введите наблюдения: все значения и все повторы должны остаться в ряду.')+`<div class="lab-controls"><div class="between wrap"><label for="ordered-data">Исходные наблюдения · разделитель «;»</label><select style="width:220px;max-width:100%" aria-label="Учебный набор наблюдений" onchange="orderedPreset(this.value)">${Object.entries(PRESETS).map(([k,v])=>`<option value="${k}">${esc(v.title)}</option>`).join('')}</select></div><textarea id="ordered-data" rows="3" style="margin-top:14px">${dataString(labState.data)}</textarea><p class="control-hint">Например: −2; 1,5; 1,5; 7. Десятичная запятая допустима. Равные числа не удаляются.</p><div class="row wrap" style="margin-top:17px"><button class="btn primary" onclick="updateOrderedSeries()">Упорядочить и проверить</button><button class="btn ghost" onclick="exportLab()">${ico('download')} Скачать CSV</button></div><div id="ordered-error" class="lab-result-error" role="status" aria-live="polite"></div></div><div id="ordered-result"></div>`;updateOrderedSeries()}
function orderedPreset(key){$('ordered-data').value=dataString(PRESETS[key].data);updateOrderedSeries()}
function updateOrderedSeries(){try{const data=parseDataset($('ordered-data').value),st=basicStats(data);labState.data=data;labState.csv=data.map((x,i)=>[i+1,x,st.sorted[i]]);labState.csvHeaders=['Номер / позиция','Исходная запись','Число на позиции упорядоченного ряда'];$('ordered-error').textContent='';$('ordered-result').innerHTML=labTiles([{value:st.n,label:'Объём n · не изменился'},{value:dataString([st.min]),label:'Минимум · первое число'},{value:dataString([st.max]),label:'Максимум · последнее число'},{value:dataString([Number(st.range.toPrecision(15))]),label:'Размах R'}])+`<section class="card"><h3>Вариационный ряд по возрастанию</h3><div class="ordered-values">${st.sorted.slice(0,160).map((x,i)=>`<span class="ordered-value"><small>${i+1}</small><strong>${esc(dataString([x]))}</strong></span>`).join('')}</div>${st.n>160?'<p class="small muted">На ленте первые 160 позиций; полный ряд ниже и в CSV.</p>':''}<div class="lab-notice"><strong>Проверка:</strong> до сортировки ${st.n} наблюдений, после — ${st.n}. Повторы сохранены. Каждый следующий элемент не меньше предыдущего. Размах: ${esc(dataString([st.max]))} − (${esc(dataString([st.min]))}) = ${esc(dataString([Number(st.range.toPrecision(15))]))}.</div><details class="task-detail" ${st.n<=20?'open':''}><summary>Исходная запись и полный упорядоченный ряд</summary><h4>До сортировки</h4><div class="sample-row">${esc(dataString(data))}</div><h4 style="margin-top:17px">После сортировки</h4><div class="sample-row">${esc(dataString(st.sorted))}</div></details><p class="small muted" style="margin-top:18px">Попробуйте удалить одно повторяющееся число: изменится объём. Правильная сортировка так не делает.</p></section>`;math($('ordered-result'))}catch(e){$('ordered-error').textContent=e.message;$('ordered-result').innerHTML='';labState.csv=[]}}
